package org.millenaire.common.entity;import net.minecraft.world.level.block.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.*;import org.millenaire.common.utilities.Point;import org.millenaire.common.village.Building;import org.millenaire.common.block.WoodVariant;import java.util.*;public class MillVillager extends Entity {public Point destination;public boolean extraLog=false;public Building building;public Building getGoalBuildingDest(){return building;}public int takeFromInv(Block b,int meta,int n){int taken=Math.min(n,stocks.getOrDefault(b,0));stocks.merge(b,-taken,Integer::sum);return taken;}public Map<Block,Integer> stocks;public MillVillager(){super(EntityType.PIG,null);}protected void defineSynchedData(){}protected void readAdditionalSaveData(net.minecraft.nbt.CompoundTag t){}protected void addAdditionalSaveData(net.minecraft.nbt.CompoundTag t){}public net.minecraft.network.protocol.Packet<?> getAddEntityPacket(){return null;}public Point getGoalDestPoint(){return destination;}public Building getTownHall(){return new Building();}public Item getBestAxe(){return Items.IRON_AXE;}public ItemStack[] getBestAxeStack(){return new ItemStack[]{new ItemStack(Items.IRON_AXE)};}public boolean canVillagerClearLeaves(){return true;}public int countInv(Block b,int meta){if(b==Blocks.OAK_LOG&&meta==-1){int n=0;for(var wood:WoodVariant.values())n+=stocks.getOrDefault(wood.log(),0);return n;}return stocks.getOrDefault(b,0);}public void setBlock(Point p,Block b){Point.world.put(p.pos,b.defaultBlockState());}public void swing(net.minecraft.world.InteractionHand h){}public int addToInv(Block b,int meta,int n){if(meta!=0)throw new AssertionError("Flattened items must use metadata zero");stocks.merge(b,n,Integer::sum);return n;}}